    this.input.handleInput(data);
    if (this.input.getValue() !== before) this.build(this.input.getValue());
  }
}

/** Set the given frontmatter lines (appending missing ones), keeping every other line and the file's line endings. */
function setAgentFrontmatter(content: string, fields: Record<string, string>): string | undefined {
  const match = /^(\uFEFF?---[ \t]*\r?\n)([\s\S]*?)(\r?\n---[ \t]*(?:\r?\n|$))/.exec(content);
  if (!match) return undefined;
  const lines = match[2].split(/\r?\n/);
  for (const [key, value] of Object.entries(fields)) {
    const at = lines.findIndex((line) => line.startsWith(`${key}:`));
    if (at >= 0) lines[at] = `${key}: ${value}`;
    else lines.push(`${key}: ${value}`);
  }
  return match[1] + lines.join(match[1].endsWith("\r\n") ? "\r\n" : "\n") + match[3] + content.slice(match[0].length);
}

